-- seed.sql
-- Datos de demostracion de Maquina QR.
--
-- ============================ ADVERTENCIA ============================
-- Este archivo BORRA los datos operativos antes de cargar los suyos. Es
-- deliberado: sirve tanto para poblar una base vacia con `supabase db reset`
-- como para restaurar la demo despues de que alguien la deje inconsistente.
-- Correrlo contra una base con datos reales los destruye.
-- =====================================================================
--
-- Por que session_replication_role = replica: los triggers de negocio son la
-- columna vertebral del modelo. Al insertar una linea en orden_repuestos, el
-- trigger recalcula monto_repuestos de la orden y genera el movimiento de stock
-- correspondiente. Si se cargaran los datos con los triggers activos, los
-- movimientos de stock quedarian duplicados y los montos recalculados sobre
-- montos ya calculados. Se desactivan durante la carga y se reactivan al final.
--
-- Por que jsonb_populate_recordset en vez de INSERT fila por fila: el JSON
-- lleva los nombres de las columnas, no sus posiciones, asi que agregar una
-- columna al schema no rompe este archivo.
--
-- Las credenciales de la cuenta de demostracion NO estan aca. La tabla
-- acceso_demo la crea su migracion con la fila apagada, y la clave se carga por
-- SQL aparte, para que no entre nunca al repositorio.
--
-- profiles se incluye, pero depende de que existan los usuarios en auth.users.
-- En un proyecto Supabase real los usuarios se crean por la Auth API, no por
-- SQL, asi que si esta base no los tiene, ese bloque falla y hay que crearlos
-- antes.

set session_replication_role = replica;

truncate table
  public.documentos,
  public.movimientos_stock,
  public.orden_repuestos,
  public.ordenes_mantencion,
  public.lecturas_uso,
  public.planes_mantencion,
  public.activos,
  public.repuestos,
  public.proveedores,
  public.profiles,
  public.parametros_calculo,
  public.configuracion,
  public.tipos_activo
cascade;

