-- Verificacion. Los criterios de aceptacion piden al menos 2 proveedores, 8
-- repuestos, 6 activos, 3 planes por activo y 15 ordenes historicas.
select
  (select count(*) from public.tipos_activo)       as tipos_activo,
  (select count(*) from public.proveedores)        as proveedores,
  (select count(*) from public.repuestos)          as repuestos,
  (select count(*) from public.activos)            as activos,
  (select count(*) from public.planes_mantencion)  as planes,
  (select count(*) from public.lecturas_uso)       as lecturas,
  (select count(*) from public.ordenes_mantencion) as ordenes,
  (select count(*) from public.orden_repuestos)    as lineas,
  (select count(*) from public.movimientos_stock)  as movimientos,
  (select count(*) from public.documentos)         as documentos,
  (select count(*) from public.profiles)           as perfiles;
